declare(strict_types=1);define('ATLAS_PLATFORM_DIR',dirname(__DIR__).'/plugins/atlas-platform/');require ATLAS_PLATFORM_DIR.'src/Autoloader.php';Atlas\Platform\Autoloader::register();if(!function_exists('wp_json_encode')){function wp_json_encode($value):string{return json_encode($value,JSON_THROW_ON_ERROR);}}use Atlas\Platform\Workflows\Authoring\WorkflowDraftRepository;use Atlas\Platform\Workflows\Authoring\WorkflowDraftService;use Atlas\Platform\Workflows\Authoring\WorkflowDraftValidator;function workflow_author_expect(bool$c,string$m):void{if(!$c){throw new RuntimeException($m);}echo"PASS: {$m}\n";}$repository=new class implements WorkflowDraftRepository{public array$seen=[];public function create(string$key,string$fingerprint,array$draft,int$userId):array{if(isset($this->seen[$key])){if($this->seen[$key]['fingerprint']!==$fingerprint){throw new RuntimeException('different request');}$result=$this->seen[$key]['result'];$result['replayed']=true;return$result;}$result=['workflow_id'=>'w1','workflow_version_id'=>'v1','status'=>'draft','replayed'=>false];$this->seen[$key]=compact('fingerprint','result');return$result;}};$service=new WorkflowDraftService($repository,new WorkflowDraftValidator());$input=['scope'=>'organization','slug'=>'intake','title'=>'Patient intake','summary'=>'Safe intake','steps'=>[['title'=>'Verify','instruction'=>'Verify identity.','requirement'=>'Use two identifiers.','warning'=>'Do not use room number.']]];$first=$service->create('workflow-1',$input,'org-a',9,false);$retry=$service->create('workflow-1',$input,'org-a',9,false);workflow_author_expect(!$first['replayed']&&$retry['replayed'],'workflow retries return the original immutable version');try{$bad=$input;$bad['steps']=[];$service->create('workflow-2',$bad,'org-a',9,false);throw new RuntimeException('Expected validation.');}catch(InvalidArgumentException){workflow_author_expect(true,'empty workflows are rejected before persistence');}try{$service->create('workflow-3',array_merge($input,['scope'=>'platform']),'org-a',9,false);throw new RuntimeException('Expected authorization validation.');}catch(InvalidArgumentException){workflow_author_expect(true,'platform workflows require platform management authorization');}echo"All workflow authoring tests passed.\n";
